{
  "bullets": [
    {
      "text": "The privacy policy expands beyond search to explicitly cover DuckDuckGo's browser apps, extensions, and chatbot, stating that it does not save or share search, chat, or browsing history.",
      "citations": [
        {
          "hunk": "h1",
          "side": "added",
          "quote": "We don’t save or share your search, chat, or browsing history when you search on DuckDuckGo, chat on Duck.ai, or use our apps and extensions."
        }
      ]
    },
    {
      "text": "DuckDuckGo outlines its advertising model, disclosing that ad clicks are operated by Microsoft's network under an agreement not to build user profiles from click activity.",
      "citations": [
        {
          "hunk": "h1",
          "side": "added",
          "quote": "Ad clicks are managed by Microsoft's ad network and Microsoft has committed to not associate your ad-click behavior with a user profile and to not store or share that information other than for accounting purposes."
        }
      ]
    },
    {
      "text": "The policy now addresses optional tools like Email Protection and Duck.ai, committing to only collect personal data required for those features to operate and to explain requirements before use.",
      "citations": [
        {
          "hunk": "h1",
          "side": "added",
          "quote": "For optional features, we only request personal information necessary for the feature to function and only use the information for that purpose. Before you choose to use an optional feature, we always let you know what personal information we’ll need (if any), how we’ll use it, and how you can subsequently opt out."
        }
      ]
    },
    {
      "text": "DuckDuckGo replaced its previous policy update procedure—which promised a 30-day notice with '(Updated)' in red in the site footer—with a date indicator and update message at the top of the modified policy page.",
      "citations": [
        {
          "hunk": "h1",
          "side": "removed",
          "quote": "If this policy is substantively updated, we will update the text of this page and provide notice to you at https://duckduckgo.com/about by writing '(Updated)' in red next to the link to this page (in the footer) for a period of at least 30 days."
        },
        {
          "hunk": "h1",
          "side": "added",
          "quote": "We will notify you of changes by posting the modified version on our website. We will indicate the date it was last modified below with an update message on top."
        }
      ]
    }
  ]
}

